WITH enriched AS (SELECT a.*, c.signup_date, c.segment FROM accounts a LEFT JOIN customers c ON a.customer_id = c.id), enriched_accounts AS (SELECT e.*, c.credit_limit, c.name, c.city FROM enriched e INNER JOIN customers c ON e.customer_id = c.id), attributed AS (SELECT e.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM enriched_accounts e INNER JOIN subscriptions sub ON e.customer_id = sub.customer_id AND e.signup_date >= sub.start_date AND e.signup_date < sub.end_date + INTERVAL 14 DAYS), with_latest AS (SELECT s.*, latest.amount, latest.transaction_txn_time FROM attributed s JOIN LATERAL (SELECT c.amount, c.txn_time AS transaction_txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, s.signup_date, s.credit_limit, s.name, (SELECT SUM(t2.shipping_fee) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_shipping_fee FROM with_latest s ORDER BY status DESC NULLS FIRST, credit_limit;
